"""Implementations of RTK's environment and word-count views."""
import os
import re
import subprocess


_SECRET = re.compile(r"(TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|PRIVATE_KEY|CREDENTIAL|AUTH)", re.I)


def env(args):
    filt = None
    show_all = False
    ultra = "--ultra-compact" in args
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-f", "--filter") and i + 1 < len(args):
            i += 1
            filt = args[i]
        elif a.startswith("--filter="):
            filt = a.split("=", 1)[1]
        elif a == "--show-all":
            show_all = True
        i += 1
    rows = [(k, v) for k, v in os.environ.items() if filt is None or filt.lower() in k.lower()]
    if not rows:
        return ""
    if filt and filt.upper() == "PATH" and len(rows) == 1 and rows[0][0] == "PATH":
        entries = rows[0][1].split(os.pathsep)
        lines = [f"PATH ({len(entries)} entries):"]
        for entry in entries:
            shown = entry if len(entry) <= 60 else entry[:3] + "..." + entry[-3:] + f" ({len(entry)} chars)"
            lines.append("  " + shown)
        return "PATH Variables:\n" + "\n".join("  " + x for x in lines) + "\n"
    rows.sort()
    groups = {}
    for k, v in rows:
        val = v
        if not show_all and _SECRET.search(k):
            val = (v[:2] + "****" + v[-2:]) if len(v) >= 5 else "***"
        group = "Cloud/Services" if re.search(r"AWS|AZURE|GCP|GOOGLE|CLOUD|API_KEY", k, re.I) else "Language/Runtime" if re.search(r"RUST|CARGO|NODE|NPM|PYTHON|JAVA|GO_", k, re.I) else "Other"
        groups.setdefault(group, []).append(f"{k}={val}")
    lines = []
    order = [g for g in ("Cloud/Services", "Language/Runtime", "Other") if g in groups]
    for group in order:
        if ultra:
            lines.extend(groups[group])
        else:
            lines.append(group + ":")
            lines.extend("  " + x for x in groups[group])
    return "\n".join(lines) + "\n"


def wc(args, stdin=None):
    """Run the platform wc and compact its padded output."""
    p = subprocess.run(["wc", *args], input=stdin, stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, text=True)
    out = p.stdout.splitlines()
    parsed = []
    for line in out:
        m = re.match(r"\s*(.*?)(?:\s+([^\s]+))?\s*$", line)
        if not m:
            continue
        # GNU wc places the optional filename after all numeric columns.
        fields = line.split()
        if not fields:
            continue
        nums = []
        while fields and re.fullmatch(r"\d+", fields[0]):
            nums.append(fields.pop(0))
        if nums:
            name = " ".join(fields)
            if name != "total":
                parsed.append((nums, name))
    if not parsed:
        return p.stdout, p.stderr, p.returncode
    # Native wc emits counts in the requested flag order; compact the padding.
    if len(parsed) == 1:
        nums, name = parsed[0]
        labels = []
        # RTK's default rendering uses L/W/B suffixes.
        opts = "".join(args)
        kinds = []
        if not any(x in ("-l", "--lines", "-w", "--words", "-c", "--bytes", "-m", "--chars") for x in args):
            kinds = [("L", "W", "B")]
        else:
            kinds = [("L" if x in ("-l", "--lines") else "W" if x in ("-w", "--words") else "B" if x in ("-c", "--bytes") else "C") for x in args if x in ("-l", "--lines", "-w", "--words", "-c", "--bytes", "-m", "--chars")]
        if len(kinds) == 1 and isinstance(kinds[0], tuple):
            labels = [f"{n}{k}" for n, k in zip(nums, kinds[0])]
        else:
            labels = nums
        return " ".join(labels) + (" " + os.path.basename(name) if name else "") + "\n", p.stderr, p.returncode
    # Multiple inputs: labeled rows and a compact aggregate, as RTK does.
    selected = set()
    for a in args:
        if a in ("-l", "--lines"): selected.add("L")
        elif a in ("-w", "--words"): selected.add("W")
        elif a in ("-c", "--bytes"): selected.add("B")
        elif a in ("-m", "--chars"): selected.add("C")
        elif a.startswith("-") and not a.startswith("--"):
            selected.update({"l":"L", "w":"W", "c":"B", "m":"C"}[c] for c in a[1:] if c in "lwcm")
    opts = [x for x in ("L", "W", "B", "C") if x in selected] if selected else ["L", "W", "B"]
    def fmt(nums):
        if selected:
            return " ".join(nums)
        return " ".join(f"{n}{opts[i]}" if i < len(opts) else n for i, n in enumerate(nums))
    lines, totals = [], [0] * max((len(n) for n, _ in parsed), default=0)
    for nums, name in parsed:
        for i, n in enumerate(nums): totals[i] += int(n)
        if name:
            lines.append(fmt(nums) + " " + os.path.basename(name))
    lines.append("Σ " + fmt([str(n) for n in totals]))
    return "\n".join(lines) + "\n", p.stderr, p.returncode


