"""Compact summaries for common project dependency manifests."""
import json
import os
import re
import sys

def run_deps(args):
    if args and args[0] in ('-h','--help'):
        print('Summarize project dependencies\n\nUsage: executable deps [OPTIONS] [PATH]'); return 0
    root=next((x for x in args if not x.startswith('-')),'.')
    found=False
    p=os.path.join(root,'package.json')
    if os.path.isfile(p):
        try: doc=json.load(open(p,encoding='utf-8'))
        except Exception: doc={}
        print('Node.js (package.json):'); found=True
        for key,label,ver in [('dependencies','Dependencies',True),('devDependencies','Dev Dependencies',False),('peerDependencies','Peer Dependencies',True),('optionalDependencies','Optional Dependencies',True)]:
            d=doc.get(key,{})
            if not isinstance(d,dict) or not d: continue
            print(f'  {label} ({len(d)}):')
            for name,value in sorted(d.items()):
                print(f'    {name} ({value})' if ver else f'    {name}')
    p=os.path.join(root,'Cargo.toml')
    if os.path.isfile(p):
        try: lines=open(p,encoding='utf-8').read().splitlines()
        except OSError: lines=[]
        deps=[]; active=False; name=None
        for line in lines:
            m=re.match(r'^\s*\[([^]]+)\]',line)
            if m:
                active=m.group(1) in ('dependencies','dev-dependencies','build-dependencies')
                continue
            if active:
                m=re.match(r'^\s*([\w.-]+)\s*=\s*(.+?)\s*(?:#.*)?$',line)
                if m:
                    val=m.group(2).strip().strip('"\'')
                    vm=re.search(r'version\s*=\s*["\']([^"\']+)',m.group(2))
                    deps.append((m.group(1),vm.group(1) if vm else val))
        print('Rust (Cargo.toml):'); found=True
        if deps:
            print(f'  Dependencies ({len(deps)}):')
            for n,v in deps: print(f'    {n} ({v})')
    p=os.path.join(root,'go.mod')
    if os.path.isfile(p):
        lines=open(p,encoding='utf-8',errors='replace').read().splitlines()
        module=next((x.split()[1] for x in lines if x.startswith('module ')),None)
        go=next((x.split()[1] for x in lines if x.startswith('go ')),None)
        deps=[]; block=False
        for line in lines:
            s=line.strip()
            if s.startswith('require ('): block=True; continue
            if block and s==')': block=False; continue
            if (block or s.startswith('require ')) and s and not s.startswith('//'):
                bits=s.removeprefix('require ').split()
                if len(bits)>1: deps.append((bits[0],bits[1]))
        print('Go (go.mod):'); found=True
        if module: print(f'  {module} (go {go or ""})'.rstrip())
        if deps:
            print(f'  Dependencies ({len(deps)}):')
            for n,v in deps: print(f'    {n} {v}')
    p=os.path.join(root,'pyproject.toml')
    if os.path.isfile(p):
        print('Python (pyproject.toml):'); found=True
    if not found:
        sys.stdout.write('No dependency files found in '+root)
    return 0

